This script and its associated documentation are confidential and proprietary to Coalesce.
Unauthorized reproduction, distribution, or disclosure of this material is strictly prohibited.
Coalesce permits you to copy and modify this script for the purposes of using with Coalesce but does not permit copying or modification for any other purpose.  
#}
{# == Node Type Name           : SQL Work  == #}
{# == Node Type Description    : Loads the table with custom SQL logic  == #}
{#---------------------------------------------------------------------------------------------#}

{# == To run data quality tests before data insertion == #}
{{ run_tests('Before') }}

{%- if node.materializationType == 'table' %}

    {#== Pre-SQL ==#}
    {%- set ns = namespace(cnt=0) %}
    {%- for sql in config.preSQL %}
        {%- if sql is mapping and sql.parameters is defined %}
            {%- set ns.cnt = ns.cnt + 1 %}
            {{ stage('Pre-SQL '  ~ ns.cnt )}}
            {{ sql.parameters[0] }}
        {%- endif %}
    {%- endfor %}

	{# == Truncate data before data insertion  == #}
    {%- if get_boolean_config("truncateBefore") == "true" %}
        {{ stage('Truncate ' + node.materializationType) }}
        TRUNCATE IF EXISTS {{ ref_no_link(node.location.name, node.name) }}
    {%- endif %}

	{# == Insert data from sources into Work table  == #}
    {{ stage('Load ' + node.materializationType + ' using Insert') }}
    INSERT INTO {{ ref_no_link(node.location.name, node.name) }}
    (
        {%- for col in sources[0].columns %}
            "{{ col.name }}"
            {%- if not loop.last -%},{%- endif %}
        {%- endfor %}
    )
    {{ sources[0].cteString }}
    (
        SELECT
        {%- for col in sources[0].columns %}
            {{ get_source_transform_v2(col) }} AS "{{ col.name }}"
            {%- if not loop.last -%}, {%- endif %}
        {%- endfor %}
        {{ sources[0].join }}
    )

    {#== Post-SQL ==#}
    {%- set ns = namespace(cnt=0) %}
    {%- for sql in config.postSQL %}
        {%- if sql is mapping and sql.parameters is defined %}
            {%- set ns.cnt = ns.cnt + 1 %}
            {{ stage('Post-SQL '  ~ ns.cnt ) }}
            {{ sql.parameters[0] }}
        {%- endif %}
    {%- endfor %}

{%- else %}
	{{ stage('Load Skipped for View') }}
	-- The node {{node.name}} is materialized as View. Therefore, a Load operation is not supported.
	SELECT 1 AS INFO_MESSAGE WHERE FALSE
{%- endif %}

{# == To run data quality tests after data insertion == #}
{{ run_tests('After') }}

create.templateString:
{#
    Copyright (c) 2026 Coalesce. All rights reserved.
This script and its associated documentation are confidential and proprietary to Coalesce.
Unauthorized reproduction, distribution, or disclosure of this material is strictly prohibited.
Coalesce permits you to copy and modify this script for the purposes of using with Coalesce but does not permit copying or modification for any other purpose.  
#}
{# == Node Type Name           : SQL Work  == #}
{# == Node Type Description    : This node creates work table or view  == #}
{#---------------------------------------------------------------------------------------------#}

{%- if node.materializationType == 'table' %}

    {# CreateSQL for Table #}
    {{ stage('Create ' + node.materializationType ) }}
	CREATE OR REPLACE {{ node.materializationType }} {{ ref_no_link(node.location.name, node.name) }}
	(
		{%- for col in columns %}
			"{{ col.name }}" {{ col.dataType }}
			{%- if col.nullable == false %} NOT NULL {%- endif %}
			{%- if col.defaultValue %} DEFAULT {{ col.defaultValue }} {%- endif %}
			{%- if col.description | trim | length > 0 %} COMMENT '{{ col.description | escape }}' {%- endif %}
			{%- if not loop.last -%}, {%- endif %}
		{%- endfor %}
	)
	{%- if node.description | trim | length > 0 %} COMMENT = '{{ node.description | escape }}' {%- endif %}

{%- elif node.materializationType == 'view' %}

    {# CreateSQL for View #}
    {{ stage('Create ' + node.materializationType ) }}
    CREATE OR REPLACE {{ node.materializationType }} {{ ref_no_link(node.location.name, node.name) }}
    (
        {%- for col in columns %}
            "{{ col.name }}"
            {%- if col.description | trim | length > 0 %} COMMENT '{{ col.description | escape }}' {%- endif %}
            {%- if not loop.last -%}, {%- endif %}
        {%- endfor %}
    )
    {%- if node.description | length > 0 %} COMMENT = '{{ node.description | escape }}' {%- endif %}
    AS
    {{ sources[0].cteString }}
    SELECT
    {%- for col in sources[0].columns %}
        {{ get_source_transform_v2(col) }} AS "{{ col.name }}"
        {%- if not loop.last -%}, {%- endif %}
    {%- endfor %}
    {{ sources[0].join }}
{%- endif %}

{% if node.override.create.enabled %}

    {{ node.override.create.script }}

{% else %}
    {{ stage('Create View') }}
    CREATE OR REPLACE VIEW {{ ref_no_link(node.location.name, node.name) }}
    (
        {% for col in columns %}
            "{{ col.name }}"
            {%- if col.description | length > 0 %} COMMENT '{{ col.description | escape }}'{% endif %}
            {%- if not loop.last -%}, {% endif %}
        {% endfor %}
    )
    {%- if node.description | length > 0 %} COMMENT = '{{ node.description | escape }}'{% endif %}
    AS
    {% for source in sources %}
        SELECT {% if config.selectDistinct %} DISTINCT {% endif %}
        {% for col in source.columns %}
            {{ get_source_transform(col) }} AS "{{ col.name }}"
            {%- if not loop.last -%}, {% endif %}
        {% endfor %}

        {{ source.join }}

        {% if not loop.last %}
            {% if config.insertStrategy in ['UNION', 'UNION ALL'] %}
                {{ config.insertStrategy }}
            {% else %}
                UNION
            {% endif %}
        {% endif %}
    {% endfor %}
{% endif %}

run.templateString:
    {% for test in node.tests if config.testsEnabled %}
        {% if test.runOrder == 'Before' %}
            {{ test_stage(test.name, test.continueOnFailure) }}
            {{ test.templateString }}
        {% endif %}
    {% endfor %}

{% if node.materializationType == 'table' %}
	{% if config.preSQL %}
		{{ stage('Pre-SQL') }}
		{{ config.preSQL }}
	{% endif %}



		{% if config.truncateBefore %}

			{{ stage('Truncate Stage Table') }}
			TRUNCATE IF EXISTS {{ ref_no_link(node.location.name, node.name) }}

		{% endif %}


		{% if config.insertStrategy in ['UNION', 'UNION ALL'] %}
			{{ stage( config.insertStrategy + ' Sources' | string ) }}
