					     MAX ("DIM"."{{last_modified_col}}") AS MAX_TARGET_VALUE
                    {% else %}
                        {{ get_source_transform(col) }}
                    {% endif %}
                    {%if col.name != last_modified_col %} AS "{{ col.name }}" {%endif%}
                    {%- if not loop.last %}, {% endif %}
                {% endfor %}
                {{ get_clause(source.join,'from')}}
