                 {% endif %}
                 {{ sortorder_by_colv() }} )     
                 {% if config.insertStrategy in ['UNION', 'UNION ALL'] and not loop.last %}
                     {{config.insertStrategy}}
                 {% endif %}
        {% endfor %}
                 )               
                AS "SRC"               
            ON
            {% for col in columns if col.isBusinessKey -%}
                {% if not loop.first %}
                    AND
                {% endif %}
                "SRC"."{{ col.name }}" = "TGT"."{{ col.name }}"
            {% endfor %}
            {% if config.dmlCol and deleteStrategy == 'SOFT DELETE' %}
                /* Re-insert - reactivate soft deleted record */
               WHEN MATCHED
                AND UPPER(NVL(CAST("SRC"."{{ dmlCol }}" AS STRING), '')) <> UPPER({{ dmlDelete }})
                AND "TGT"."{{ get_value_by_column_attribute("isSystemCurrentFlag") }}" = 'N'
                AND "TGT"."{{ get_value_by_column_attribute("isSystemVersion") }}" = 0
                {% if config.lastModifiedComparison %}
                AND (
                        "SRC"."{{ last_modified_col }}" > "SRC".MAX_TARGET_VALUE
                )
                {% endif %}
                THEN UPDATE SET
                    {%- for col in columns %}
                            {% if col.isSystemVersion %}
