                            {% elif col.isSystemEndDate %}
                                ,"TGT"."{{ col.name }}" = CAST('2999-12-31 00:00:00' AS TIMESTAMP)
                            {% elif col.isSystemUpdateDate %}
                                ,"TGT"."{{ col.name }}" = CAST(CURRENT_TIMESTAMP AS TIMESTAMP)
                            {% elif col.isSystemStartDate %}
                                , "TGT"."{{col.name}}" = CAST(CURRENT_TIMESTAMP AS TIMESTAMP)
                            {% endif %}
                        {%- endfor %}
                    {%- for col in columns if not (col.isBusinessKey or
                                                    col.isSurrogateKey or
                                                    col.isSystemVersion or
                                                    col.isSystemCurrentFlag or
                                                    col.isSystemStartDate or
                                                    col.isSystemEndDate or
                                                    col.isSystemCreateDate or
                                                    col.isSystemUpdateDate) %},
                        "TGT"."{{ col.name }}" = "SRC"."{{ col.name }}"
                    {% endfor %}
            {% endif %}
                {% if config.dmlCol %}
                    {% if deleteStrategy == 'SOFT DELETE' %}
                        /* Soft Delete */
                        WHEN MATCHED AND             
                        "SRC"."{{ dmlCol }}" = {{ dmlDelete }}
                        {% if config.lastModifiedComparison %}
                        AND (
                            {% if useCurrentTimeStamp %}
                                COALESCE("SRC"."{{ last_modified_col }}", CURRENT_TIMESTAMP()) > "SRC".MAX_TARGET_VALUE
                            {% else %}
                                "SRC"."{{ last_modified_col }}" > "SRC".MAX_TARGET_VALUE
                            {% endif %}
                        )
                        {% endif %}
                        THEN UPDATE SET
                            "TGT"."{{ dmlCol }}" = "SRC"."{{ dmlCol }}"
                        {%- for col in columns %}
                            {% if col.isSystemVersion %}
                                ,"TGT"."{{ col.name }}" = 0
                            {% elif col.isSystemCurrentFlag %}
                                ,"TGT"."{{ col.name }}" = 'N'
                            {% elif col.isSystemEndDate %}
                                ,"TGT"."{{ col.name }}" = DATEADD(MILLISECONDS, -1, CAST(CURRENT_TIMESTAMP AS TIMESTAMP))
                            {% elif col.isSystemUpdateDate %}
                                ,"TGT"."{{ col.name }}" = CAST(CURRENT_TIMESTAMP AS TIMESTAMP)
                            {% endif %}
                        {%- endfor %}
                    {% elif deleteStrategy == 'HARD DELETE' %}
                        /* Hard Delete */
                        WHEN MATCHED
                        AND "SRC"."{{ dmlCol }}" = {{ dmlDelete }}
                        {% if config.lastModifiedComparison %}
                        AND (
                                "SRC"."{{ last_modified_col }}" > "SRC".MAX_TARGET_VALUE
                        )
                        {% endif %}
                        THEN DELETE

                    {% endif %}

                {% endif %}
            WHEN MATCHED 
             {%if not config.lastModifiedComparison%}
                {% for col in columns if not (   col.isBusinessKey or
                                                        col.isSurrogateKey or
                                                        col.isSystemVersion or
                                                        col.isSystemCurrentFlag or
                                                        col.isSystemStartDate or
                                                        col.isSystemEndDate or
                                                        col.isSystemUpdateDate or
                                                        col.isSystemCreateDate) %}
                    {% if loop.first %}
                        AND (
                        {% else %}
                            OR
                        {% endif %}

                    {% if col.dataType == 'GEOGRAPHY' %}
                        (
                            ST_DISTANCE(
                                (CASE 
                                    WHEN "SRC"."{{ col.name }}" IS NULL THEN TO_GEOGRAPHY('POINT(0 0)') 
                                    ELSE "SRC"."{{ col.name }}" 
                                END),
                                (CASE 
                                    WHEN "TGT"."{{ col.name }}" IS NULL THEN TO_GEOGRAPHY('POINT(0 0)') 
                                    ELSE "TGT"."{{ col.name }}" 
                                END)
                            ) > 0
                        )
                    {% elif col.dataType == 'GEOMETRY' %}
                        (
                            ST_DISTANCE(

                                    (CASE 
                                        WHEN "SRC"."{{ col.name }}" IS NULL THEN TO_GEOMETRY('POINT(0 0)') 
                                        ELSE "SRC"."{{ col.name }}" 
                                    END),
                                    (CASE 
                                        WHEN "TGT"."{{ col.name }}" IS NULL THEN TO_GEOMETRY('POINT(0 0)') 
                                        ELSE "TGT"."{{ col.name }}" 
                                END)
                            ) > 0
                        )
                    {% else %}
                            (

                                NVL(CAST("SRC"."{{ col.name }}" AS STRING), '**NULL**') <> 
                                NVL(CAST("TGT"."{{ col.name }}" AS STRING), '**NULL**')
                            )
                    {% endif %}

                    {% if loop.last %}
                        )
                    {% endif %}
                {% endfor %}
             {%else%}  
                    AND ("SRC".COMPARISON_VALUE > "SRC".MAX_TARGET_VALUE )
             {%endif%}
            THEN UPDATE SET
            {%- for col in columns if not (  col.isBusinessKey or
                                                    col.isSurrogateKey or
                                                    col.isSystemVersion or
                                                    col.isSystemCurrentFlag or
                                                    col.isSystemStartDate or
                                                    col.isSystemCreateDate) %}
                    "TGT"."{{ col.name }}" = "SRC"."{{ col.name }}"
                {% if not loop.last %}, {% endif %}
            {% endfor %}
            WHEN NOT MATCHED 
            {% if config.dmlCol and deleteStrategy != 'NO DELETE' %}
                AND UPPER(NVL(CAST("SRC"."{{ dmlCol }}" AS STRING), '')) <> UPPER({{ dmlDelete }})
            {% endif %}
            THEN INSERT (
            {%- for col in columns if not col.isSurrogateKey %}
                "{{ col.name }}"
                {% if not loop.last %}, {% endif %}
            {% endfor -%}
            )
            VALUES (
            {%- for col in columns if not col.isSurrogateKey %}
                "SRC"."{{ col.name }}"
                {% if not loop.last %}, {% endif %}
            {% endfor -%}
            )

    {% else %}

        {# == Executed if neither business key or change tracking is not specified  == #}


            {{ stage('Insert ' + 'Sources' | string ) }}
            INSERT INTO {{ ref_no_link(node.location.name, node.name) }}
            (
                {% for col in columns if not col.isSurrogateKey %}
                    "{{ col.name }}"
                    {%- if not loop.last -%},{% endif %}
                {% endfor %}
            )


        {% for source in sources %}
            (SELECT
            {% if config.selectDistinct %}
