        {% endif %}
    {% endfor %}
{% if isTimestampComparison  %}

{{ test_stage(
    'Checking NULL values for ' ~ last_modified_col ~ ' column',
    false
) }}

{% set ns = namespace(first=true) %}

{% for source in sources %}

    {% for col in source.columns if col.name == last_modified_col %}

        {% set col_transform = get_source_transform(col) %}

        {% if col_transform is not none and col_transform != 'NULL' %}

            {% if not ns.first %}
                UNION ALL
            {% endif %}

            SELECT 1

            {{ get_clause(source.join,'from') }}

            WHERE {{ col_transform }} IS NULL

            {{ get_clause(source.join) }}

            {% set ns.first = false %}
			 /* If NULL values are detected, this stage will fail and execution will be terminated */

        {% endif %}

    {% endfor %}

{% endfor %}

{% endif %}	
    {% if node.materializationType == 'table' %}

    {# == Queries to be excuted before data insertion  == #}

        {% if config.preSQL %}
            {{ stage('Pre-SQL') }}
            {{ config.preSQL }}
        {% endif %}

    {# == Truncate data before data insertion  == #}

        {% if config.truncateBefore %}
            {{ stage('Truncate Fact Table') }}
            TRUNCATE IF EXISTS {{ ref_no_link(node.location.name, node.name) }}
        {% endif %}

            {% if has_business_key %}

            {# == Executed if business key is specified  == #}


                {{ stage('MERGE ' + ' Sources' | string ) }}
                MERGE INTO {{ ref_no_link(node.location.name, node.name) }} "TGT"
                USING (

                {% for source in sources %}
                    (SELECT
                    {% if config.selectDistinct %}
                    DISTINCT
                    {% endif %}
                    {% for col in source.columns %}	    
                       {% if col.name == last_modified_col %}
					     {{ get_source_transform(col) }} AS "{{ col.name }}",
						 {{ get_source_transform(col) }} AS COMPARISON_VALUE,
					     MAX ("DIM"."{{last_modified_col}}") AS MAX_TARGET_VALUE
                       {%else%}
                        {{ get_source_transform(col) }} AS "{{ col.name }}"
                       {%endif%}
                       {%- if not loop.last %}, {% endif %}
                    {%endfor%}
                    {{ get_clause(source.join,'from')}}
                    {%if config.lastModifiedComparison%}	        
                        LEFT JOIN {{ ref_no_link(node.location.name, node.name) }} "DIM" ON
                             {% for col in source.columns if col.isBusinessKey -%}
                                {% if not loop.first %}
                                    AND
                                {% endif %}
                                {{ get_source_transform(col) }} = "DIM"."{{ col.name }}"
                            {% endfor %}
                  {%endif%}
                   {% set clause = get_clause(source.join) %}
                   {% if clause %}
                      {{ ("WHERE " ~ clause.strip()[3:].strip()) if clause.strip().upper().startswith('AND') else clause }}
                   {% endif %}
                    {% if config.groupByAll or config.lastModifiedComparison%}
                        GROUP BY ALL
                    {% endif %}
                    {{ sortorder_by_colv() }})
                    {% if config.insertStrategy in ['UNION', 'UNION ALL'] and not loop.last %}
                        {{config.insertStrategy}}
                    {% endif %}
                {% endfor %}   
                    )
                    AS "SRC"
                ON
                {% for col in columns if col.isBusinessKey -%}
                    {% if not loop.first %}
                        AND
                    {% endif %}
                    "SRC"."{{ col.name }}" = "TGT"."{{ col.name }}"
                {% endfor %}
    WHEN MATCHED
                {%if not config.lastModifiedComparison%}
					{% for col in columns if not (col.isBusinessKey or col.isSystemUpdateDate or col.isSystemCreateDate) %}

						{% if loop.first %}
							AND (
						{% else %}
							OR
						{% endif %}
						{% if col.dataType == 'GEOGRAPHY' %}
							(
								ST_DISTANCE(
									(CASE 
										WHEN "SRC"."{{ col.name }}" IS NULL THEN TO_GEOGRAPHY('POINT(0 0)') 
										ELSE "SRC"."{{ col.name }}" 
									END),
									(CASE 
										WHEN "TGT"."{{ col.name }}" IS NULL THEN TO_GEOGRAPHY('POINT(0 0)') 
										ELSE "TGT"."{{ col.name }}" 
									END)
								) > 0
							)
						{% elif col.dataType == 'GEOMETRY' %}
							(
								ST_DISTANCE(
									(CASE 
										WHEN "SRC"."{{ col.name }}" IS NULL THEN TO_GEOMETRY('POINT(0 0)') 
										ELSE "SRC"."{{ col.name }}" 
									END),
									(CASE 
										WHEN "TGT"."{{ col.name }}" IS NULL THEN TO_GEOMETRY('POINT(0 0)') 
										ELSE "TGT"."{{ col.name }}" 
									END)
								) > 0
							)
						{% else %}
							(
								NVL(CAST("SRC"."{{ col.name }}" AS STRING), '**NULL**') <> 
								NVL(CAST("TGT"."{{ col.name }}" AS STRING), '**NULL**')
							)
						{% endif %}
						{% if loop.last %}
							)
						{% endif %}
					{% endfor %}  
                {%else%} 
                    AND ("SRC".COMPARISON_VALUE > "SRC".MAX_TARGET_VALUE)
                {%endif%}
                THEN UPDATE SET
                {%- for col in columns if not (col.isBusinessKey or col.isSystemCreateDate) %}
                        "TGT"."{{ col.name }}" = "SRC"."{{ col.name }}"
                    {% if not loop.last %}, {% endif %}
                {% endfor %}
                WHEN NOT MATCHED THEN
                INSERT (
                {%- for col in columns if not col.isSurrogateKey %}
                    "{{ col.name }}"
                    {% if not loop.last %}, {% endif %}
                {% endfor -%}
                )
                VALUES (
                {%- for col in columns if not col.isSurrogateKey %}
                    "SRC"."{{ col.name }}"
                    {% if not loop.last %}, {% endif %}
                {% endfor -%}
                )

            {% else %}

               {# == Executed if business key is not specified  == #}

                {{ stage('Insert ' + ' Sources' | string ) }}

                    INSERT INTO {{ ref_no_link(node.location.name, node.name) }}
                    (
                        {% for col in columns %}
                            "{{ col.name }}"
                            {%- if not loop.last -%},{% endif %}
                        {% endfor %}
                    )
                {% for source in sources %}
                    (SELECT
                    {% if config.selectDistinct %}
                    DISTINCT
                    {% endif %}
                    {% for col in source.columns %}
                        {{ get_source_transform(col) }} AS "{{ col.name }}"
                        {%- if not loop.last -%}, {% endif %}
                    {% endfor %}
                    {{ source.join }}
                 {% if config.groupByAll %}
                     GROUP BY ALL
                 {% endif %}
                 {{ sortorder_by_colv() }})
                 {% if config.insertStrategy in ['UNION', 'UNION ALL'] and not loop.last %}
                     {{config.insertStrategy}}
                 {% endif %}
                {% endfor %} 
            {% endif %}

 {# == Queries to be excuted post data insertion  == #}

        {% if config.postSQL %}
            {{ stage('Post-SQL') }}
            {{ config.postSQL }}
        {% endif %}
    {% else %}
        {{ stage('Load Skipped for View') }}
        -- The node {{node.name}} is materialized as View. Therefore, a Load operation is not supported.
        SELECT 1 AS INFO_MESSAGE WHERE FALSE
    {% endif %}

{# == To run data quality tests after data insertion == #}

    {% if config.testsEnabled %}
        {% for test in node.tests %}
            {% if test.runOrder == 'After' %}
                {{ test_stage(test.name, test.continueOnFailure) }}
                {{ test.templateString }}
            {% endif %}
        {% endfor %}

        {% for column in columns %}
            {% for test in column.tests %}
                {{ test_stage(column.name + ": " + test.name) }}
                {{ test.templateString }}
            {% endfor %}
        {% endfor %}

    {% endif %}

